import http from "node:http";
import { readFile, stat } from "node:fs/promises";
import path from "node:path";

const MIME_TYPES = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "application/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".png": "image/png",
  ".svg": "image/svg+xml; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
};

function parseLimit(limit) {
  if (typeof limit === "number") {
    return limit;
  }

  if (typeof limit !== "string") {
    return 1024 * 100;
  }

  const match = limit.trim().match(/^(\d+)(kb|mb|gb)?$/iu);

  if (!match) {
    return 1024 * 100;
  }

  const value = Number(match[1]);
  const unit = (match[2] || "b").toLowerCase();
  const multipliers = {
    b: 1,
    kb: 1024,
    mb: 1024 * 1024,
    gb: 1024 * 1024 * 1024,
  };

  return value * (multipliers[unit] || 1);
}

function enhanceResponse(res) {
  res.status = function status(code) {
    res.statusCode = code;
    return res;
  };

  res.json = function json(payload) {
    if (!res.headersSent) {
      res.setHeader("Content-Type", "application/json; charset=utf-8");
    }

    res.end(JSON.stringify(payload));
    return res;
  };

  res.send = function send(payload) {
    if (typeof payload === "object" && payload !== null) {
      return res.json(payload);
    }

    res.end(String(payload));
    return res;
  };

  return res;
}

function flattenHandlers(handlers) {
  return handlers.flatMap((handler) =>
    Array.isArray(handler) ? flattenHandlers(handler) : [handler],
  );
}

function normalizeMountPath(mountPath) {
  if (!mountPath || mountPath === "/") {
    return "/";
  }

  return mountPath.endsWith("/") && mountPath.length > 1
    ? mountPath.slice(0, -1)
    : mountPath;
}

function matchesMountPath(requestPath, mountPath) {
  if (!mountPath || mountPath === "/") {
    return true;
  }

  return requestPath === mountPath || requestPath.startsWith(`${mountPath}/`);
}

function getRelativeMountPath(requestPath, mountPath) {
  if (!mountPath || mountPath === "/") {
    return requestPath;
  }

  const relativePath = requestPath.slice(mountPath.length);

  return relativePath || "/";
}

function createRouteRegistrar(routes, method) {
  return function register(path, ...handlers) {
    routes.push({
      method,
      path,
      handlers: flattenHandlers(handlers),
    });
  };
}

function createApp() {
  const middlewares = [];
  const errorMiddlewares = [];
  const routes = [];

  const app = {
    use(pathOrHandler, maybeHandler) {
      const hasMountPath = typeof pathOrHandler === "string";
      const mountPath = hasMountPath
        ? normalizeMountPath(pathOrHandler)
        : "/";
      const handler = hasMountPath ? maybeHandler : pathOrHandler;

      if (typeof handler !== "function") {
        throw new TypeError("Middleware must be a function.");
      }

      if (handler.length === 4) {
        errorMiddlewares.push({ mountPath, handler });
      } else {
        middlewares.push({ mountPath, handler });
      }

      return app;
    },
    get: createRouteRegistrar(routes, "GET"),
    post: createRouteRegistrar(routes, "POST"),
    listen(port, callback) {
      const server = http.createServer(async (req, res) => {
        enhanceResponse(res);

        const requestUrl = new URL(req.url, "http://127.0.0.1");
        req.path = requestUrl.pathname;
        req.query = Object.fromEntries(requestUrl.searchParams.entries());

        const route = routes.find(
          (candidate) =>
            candidate.method === req.method && candidate.path === req.path,
        );

        const stack = route
          ? [
              ...middlewares.filter((layer) =>
                matchesMountPath(req.path, layer.mountPath),
              ),
              ...route.handlers.map((handler) => ({
                mountPath: "/",
                handler,
              })),
            ]
          : [
              ...middlewares.filter((layer) =>
                matchesMountPath(req.path, layer.mountPath),
              ),
              {
                mountPath: "/",
                handler: (_req, response) => {
                  response.status(404).json({
                    ok: false,
                    error: "Not found.",
                  });
                },
              },
            ];

        let index = -1;
        let errorIndex = -1;

        const runErrorMiddleware = async (error) => {
          errorIndex += 1;
          const layer = errorMiddlewares[errorIndex];
          const middleware = layer?.handler;

          if (!middleware) {
            if (!res.writableEnded) {
              const statusCode = error?.statusCode || 500;

              res.status(statusCode).json({
                ok: false,
                error:
                  statusCode >= 500
                    ? "Internal server error."
                    : error?.message || "Request failed.",
              });
            }

            return;
          }

          try {
            const originalPath = req.path;

            if (layer?.mountPath) {
              req.path = getRelativeMountPath(req.path, layer.mountPath);
            }

            await middleware(error, req, res, runErrorMiddleware);
            req.path = originalPath;
          } catch (nextError) {
            await runErrorMiddleware(nextError);
          }
        };

        const runMiddleware = async (error) => {
          if (error) {
            await runErrorMiddleware(error);
            return;
          }

          index += 1;
          const layer = stack[index];
          const middleware = layer?.handler;

          if (!middleware || res.writableEnded) {
            return;
          }

          try {
            const originalPath = req.path;

            if (layer?.mountPath) {
              req.path = getRelativeMountPath(req.path, layer.mountPath);
            }

            await middleware(req, res, runMiddleware);
            req.path = originalPath;
          } catch (nextError) {
            await runErrorMiddleware(nextError);
          }
        };

        await runMiddleware();
      });

      return server.listen(port, callback);
    },
  };

  return app;
}

function json(options = {}) {
  const maxBytes = parseLimit(options.limit);

  return async (req, _res, next) => {
    if (req.body !== undefined) {
      next();
      return;
    }

    if (req.method === "GET" || req.method === "HEAD") {
      req.body = {};
      next();
      return;
    }

    const contentType = req.headers["content-type"] || "";

    if (!contentType.toLowerCase().includes("application/json")) {
      req.body = {};
      next();
      return;
    }

    try {
      let size = 0;
      const chunks = [];

      for await (const chunk of req) {
        size += chunk.length;

        if (size > maxBytes) {
          const error = new Error("Payload too large.");
          error.statusCode = 413;
          throw error;
        }

        chunks.push(chunk);
      }

      const rawBody = Buffer.concat(chunks).toString("utf8").trim();
      req.body = rawBody ? JSON.parse(rawBody) : {};
      next();
    } catch (error) {
      if (!error.statusCode) {
        error.statusCode = 400;
      }

      next(error);
    }
  };
}

function express() {
  return createApp();
}

express.json = json;
express.static = function staticMiddleware(rootDir) {
  const resolvedRoot = path.resolve(rootDir);
  const rootPrefix = `${resolvedRoot}${path.sep}`.toLowerCase();

  return async (req, res, next) => {
    try {
      const requestedPath = req.path === "/" ? "/index.html" : req.path;
      const safePath = requestedPath.replace(/^\/+/, "");
      const filePath = path.resolve(resolvedRoot, safePath);
      const normalizedFilePath = filePath.toLowerCase();

      if (
        normalizedFilePath !== resolvedRoot.toLowerCase() &&
        !normalizedFilePath.startsWith(rootPrefix)
      ) {
        next();
        return;
      }

      const fileStat = await stat(filePath);

      if (!fileStat.isFile()) {
        next();
        return;
      }

      const extension = path.extname(filePath).toLowerCase();
      res.setHeader(
        "Content-Type",
        MIME_TYPES[extension] || "application/octet-stream",
      );
      res.end(await readFile(filePath));
    } catch (_error) {
      next();
    }
  };
};

export { json };
export default express;
